            "source_path": "src/index.ts",
            "line_start": 2899,
            "line_end": 2929,
            "observation": "强宿主耦合和闭锁影响可用性。"
          },
          {
            "kind": "source_inspection",
            "source_path": "test/modern-policy.test.mjs",
            "line_start": 10,
            "line_end": 30,
            "observation": "必要授权反例的源码依据。"
          }
        ],
        "unknowns": [
          {
            "issue": "目标宿主完整端点/帧与状态恢复闭包仍待核查。",
            "impact": "阻碍当前升级为可控多用户试用。",
            "next_step": "先按固定版本完成可达面映射，形成明确拒绝和恢复条件后再判断试用范围。"
          }
        ]
      }
    ]
