      "content": "{\n  \"name\": \"dsh-ui-auth\",\n  \"version\": \"0.7.1\",\n  \"description\": \"DSH Web UI 认证网关：登录保护全部 HTTP/WS 接口；用户管理、邀请码注册、TOTP 两步验证与通行密钥（Passkey/WebAuthn）登录。\",\n  \"type\": \"module\",\n  \"main\": \"./lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"src\",\n    \"docs\",\n    \"assets\",\n    \"cordis.patch.yml\",\n    \"LICENSE\",\n    \"README.md\",\n    \"CHANGELOG.md\",\n    \"CONTRIBUTING.md\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.json && node build/client.mjs\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit && tsc -p tsconfig.client.json\",\n    \"test\": \"npm run build && node --check lib/index.js && node --check lib/webauthn.js && node --check lib/client.js && node --check lib/passkey-browser.js && node --check lib/modern-gateway.js && node --check lib/modern-policy.js && node test/crypto-vectors.cjs && node test/totp-vectors.mjs && node test/client-smoke.cjs && node test/host-smoke.mjs && node test/login-page-check.mjs && node test/security-suite.mjs && node test/modern-policy.test.mjs && node test/profile-crypto.test.mjs && node test/profile-envelope.test.mjs && node test/profile-service.test.mjs && node test/user-routes.test.mjs && node test/profile-keys.test.mjs && node test/i18n.test.mjs\",\n    \"prepack\": \"npm test\",\n    \"verify:clean\": \"npm run build && git diff --exit-code -- lib\",\n    \"store:check\": \"node test/store-contract-check.mjs\",\n    \"test:compat:0.1.5\": \"node test/live-015-check.mjs\",\n    \"test:ui\": \"node test/live-ui-check.mjs\",\n    \"test:passkey\": \"node test/live-passkey-check.mjs\",\n    \"docs:matrix\": \"node build/docs-matrix.mjs\",\n    \"assets\": \"node test/shot.mjs\",\n    \"test:pages\": \"node test/live-user-pages-check.mjs\",\n    \"test:compat:0.2.0\": \"node test/live-020-check.mjs\",\n    \"test:compat:mat