    {
      "path": "src/modern-policy.ts",
      "content": "/**\n * DSH 0.1.5 Remote surface policy — reviewed by endpoint, ordinary users fail closed.\n *\n * Source of truth for the reviewed surface: DSH `dsh-v0.1.5-rc.1`\n * (`packages/api/*` `@Remote` descriptors, `packages/api/remotes/src/remote-events.ts`).\n * Unknown endpoints and unknown events are denied; ownership comes from the\n * plugin's own attribution table (`owners`), never from client-supplied fields.\n *\n * Wire conventions this module encodes:\n * - unary args are `payload.args`; most methods nest one `request` object, flat\n *   methods (`settings/*`, `credentials/*`, `workspaceFiles/*`, `llm/*`, `*Id`\n *   scoped verbs) carry their fields directly;\n * - `session/list` is the one method whose wire field is `_request`;\n * - `session/page` / `session/follow` address sessions durably\n *   (`{ kind: 'session' | 'subagent', sessionId, parentSessionId?, childSessionId? }`);\n * - agent-scoped verbs carry `agentId`, a SessionId;\n * - `workspaceFiles/*` carry `workspaceFileScopeId`, also a SessionId.\n *\n * Baseline note: this module is the only policy path. v0.7.0 removed the legacy\n * dotted/`apiProxy` transport, so a host without `connection.authorizeIndex`\n * (DSH 0.1.1-rc.2) is refused at startup instead of falling back.\n */\n\n/** One authenticated principal; `role` is `'admin'` for administrators. */\nexport interface Principal {\n  readonly username: string\n  readonly role: string\n}\n\n/** Ownership queries and attribution used by the policy (supplied by `index.ts`). */\nexport interface OwnershipLookup {\n  session(id: string): string\n  workspace(id: string): string\n  sessionExists(id: string): Promise<boolean>\n  claimSession(id: string, username: string): Promise<void>\n}\n\n/** Any decoded JSON object. */\nexport type JsonObject = Record<string, unknown>\n\n/** Per-stream correlation state: the delivered `clientId` plus pending waterfall ids. */\nexport interface StreamCorrelation {\n  clientId?: string\n  /** Login-token hash of the generation that owns this stream (set by the gateway). */\n  login?: string\n  events: Set<string>\n}\n\nexport const object = (value: unknown): value is JsonObject =>\n  value !== null && typeof value === 'object' && !Array.isArray(value)\n\nexport const nonempty = (value: unknown): value is string =>\n  typeof value === 'string' && value.length > 0 && value.length <= 256\n\n/** Own-session session methods addressed by `request.sessionId`. */\nconst SESSION_BY_ID = new Set(['prompt', 'attachment', 'cancel', 'rename', 'selectModel', 'updateQueue', 'fork'])\n/** Own-workspace workspace methods addressed by `request.workspaceId`. */\nconst WORKSPACE_BY_ID = new Set(['rename', 'delete', 'insertBefore', 'insertSessionBefore'])\n/** Read-only, owner-filtered session endpoints. */\nconst SESSION_READ = new Set(['list', 'search', 'modelCatalog', 'canOpenWorkspacePath'])\n/** Flat read-only global metadata an ordinary user may see (redacted by the host). */\nconst SHARED_READ = new Set(['settings/describe', 'llm/listProviders', 'llm/listConfigurableProviders'])\n/** Plugin-manager reads the settings page performs on load; its write verbs stay administrator-only. */\nconst PLUGIN_MANAGER_READ = new Set(['listPlugins', 'listBundles', 'registries', 'inspect'])\n/** Interactive question endpoints: agent-scoped or session-scoped, both are ownership proofs. */\nconst SESSION_INTERACTIVE = new Set(['userQuestions/answer', 'userQuestions/attachWait'])\n/** Office-to-PDF carries positional args `(workspaceFileScopeId, path, priority)`. */\nconst OFFICE_TO_PDF_SCOPE_INDEX = 0\n\n/** The raw `args` value of a Remote payload (an object, or a positional array). */\nfunction rawArgs(payload: unknown): unknown {\n  return object(payload) ? payload.args : undefined\n}\n\n/** The single `args` object of a Remote payload, or undefined when malformed. */\nexport function remoteArgs(payload: unknown): JsonObject | undefined {\n  if (!object(payload) || Object.keys(payload).length !== 1 || !object(payload.args)) return undefined\n  return payload.args\n}\n\n/** Normalize one endpoint's args into its request object (nested or flat). */\nfunction requestOf(args: JsonObject): JsonObject {\n  if (object(args.request)) return args.request\n  return args\n}\n\nexport interface ModernPolicy {\n  session(principal: Principal, id: unknown): boolean\n  workspace(principal: Principal, id: unknown): boolean\n  authorize(principal: Principal, endpoint: string, payload: unknown, stream?: boolean): Promise<boolean>\n  result(principal: Principal, endpoint: string, value: unknown): Promise<unknown>\n  frame(principal: Principal, endpoint: string, value: unknown, correlation: StreamCorrelation): unknown\n}\n\n/** 普通用户可用的模型范围（R2：按登录用户裁剪 provider 列表与模型目录）。 */\nexport interface ModelEntitlement {\n  /** 允许的 provider 路由 id（如 `deepseek`）。 */\n  readonly providers: readonly string[]\n  /** 允许的 provider + model 组合；provider 已在上表列出的，仍需逐模型登记。 */\n  readonly models: readonly { readonly provider: string; readonly model: string }[]\n}\n\nexport interface ModernPolicyOptions {\n  /**\n   * 按登录用户返回模型授权范围。返回 `undefined` 表示不裁剪（保持只读放行）；\n   * 管理员从不受此限制。未提供该回调时行为与以前完全一致。\n   */\n  readonly entitlement?: (principal: Principal) => Promise<ModelEntitlement | undefined> | ModelEntitlement | undefined\n}\n\n/** provider 行/模型行的字段名在不同包里有 `id`/`provider`/`model` 等写法，这里做容错读取。 */\nconst rowId = (row: unknown): string | undefined => {\n  if (!object(row)) return undefined\n  for (const key of ['id', 'provider', 'providerId', 'name']) {\n    const value = row[key]\n    if (nonempty(value)) return value\n  }\n  return undefined\n}\nconst rowModel = (row: unknown): string | undefined => {\n  if (!object(row)) return undefined\n  for (const key of ['id', 'model', 'modelId', 'name']) {\n    const value = row[key]\n    if (nonempty(value)) return value\n  }\n  return undefined\n}\n\nexport function createModernPolicy(owners: OwnershipLookup, options: ModernPolicyOptions = {}): ModernPolicy {\n  /** 取当前主体的授权范围（管理员永远不受限）。 */\n  const entitlementOf = async (principal: Principal): Promise<ModelEntitlement | undefined> => {\n    if (principal.role === 'admin' || options.entitlement === undefined) return undefined\n    return await options.entitlement(principal)\n  }\n  const allowedProvider = (scope: ModelEntitlement, provider: unknown): boolean =>\n    nonempty(provider) && scope.providers.includes(provider)\n  const allowedModel = (scope: ModelEntitlement, provider: unknown, model: unknown): boolean =>\n    nonempty(provider) && nonempty(model)\n    && scope.models.some(entry => entry.provider === provider && entry.model === model)\n  const arrayOf = (value: unknown): unknown[] => (Array.isArray(value) ? value : [])\n  const session = (principal: Principal, id: unknown): boolean =>\n    nonempty(id) && (principal.role === 'admin' || owners.session(id) === principal.username)\n  const workspace = (principal: Principal, id: unknown): boolean =>\n    nonempty(id) && (principal.role === 'admin' || owners.workspace(id) === principal.username)\n  const ownMap = (principal: Principal, value: unknown): JsonObject =>\n    Object.fromEntries(Object.entries(object(value) ? value : {}).filter(([id]) => session(principal, id)))\n  const workspaceValue = (principal: Principal, value: JsonObject): JsonObject => ({\n    ...value,\n    sessionIds: arrayOf(value.sessionIds).filter(id => session(principal, id)),\n  })\n  const workspaceBaseline = (principal: Principal, value: unknown): JsonObject => {\n    const baseline = object(value) ? value : {}\n    return {\n      items: arrayOf(baseline.items).filter(item => workspace(principal, object(item) ? item.workspaceId : undefined))\n        .map(item => workspaceValue(principal, item as JsonObject)),\n      archivedSessionIds: arrayOf(baseline.archivedSessionIds).filter(id => session(principal, id)),\n    }\n  }\n  /** An agent-scoped verb is authorized by the Session that owns the agent. */\n  const agent = (principal: Principal, args: JsonObject): boolean => session(principal, args.agentId)\n\n  function authorizeSession(args: JsonObject, principal: Principal): boolean {\n    const request = requestOf(args)\n    if (request.address !== undefined) {\n      const address = request.address\n      if (!object(address)) return false\n      if (address.kind === 'session') return session(principal, address.sessionId)\n      // The Session Controller verifies the child's durable parent and mode before opening it.\n      if (address.kind === 'subagent') return session(principal, address.parentSessionId) && nonempty(address.childSessionId)\n      return false\n    }\n    return session(principal, request.sessionId)\n  }\n\n  return {\n    session,\n    workspace,\n    async authorize(principal, endpoint, payload, stream = false) {\n      // 非标准信封（如 @xmanrui/dsh-im 的 `{method, payload}`）：此前被判为「畸形」而在 **admin 放行之前**\n      // 拒绝，导致其管理页报 management-unreachable（Issue #3，PR #5 by @HeathZero）。\n      // 这里**泛化识别**而不是硬编码某个插件的命名空间：形状完备即按管理员放行，普通用户继续走下面的默认拒绝。\n      if (object(payload) && typeof (payload as JsonObject).method === 'string'\n        && object((payload as JsonObject).payload) && (payload as JsonObject).args === undefined) {\n        return principal.role === 'admin'\n      }\n      // Remote 入参有两种线上形态：命名对象（`{args:{...}}`）与位置数组（如 officeToPdf 的\n      // `(workspaceFileScopeId, path, priority)`）。数组形态按空对象继续，由对应规则自行读取位置参数；\n      // 其它端点拿到空对象后仍会因缺少归属证据而被拒。\n      const raw = rawArgs(payload)\n      const args = remoteArgs(payload) ?? (Array.isArray(raw) ? {} : undefined)\n      if (args === undefined) return false\n      if (principal.role === 'admin') return true\n      const request = requestOf(args)\n      const [namespace, method, extra] = endpoint.split('/')\n      if (extra !== undefined) return false\n      if (stream) {\n        if (endpoint === '$events') return true\n        if (endpoint === 'session/control') return true\n        if (endpoint === 'session/follow') return authorizeSession(args, principal)\n        if (endpoint === 'workspace/follow') return true\n        if (endpoint === 'workspaceFiles/changes') return session(principal, args.workspaceFileScopeId)\n        return false\n      }\n      if (endpoint === '$events/result') {\n        // Correlated by the gateway against delivered waterfall frames; never by payload alone.\n        return false\n      }\n      if (SHARED_READ.has(endpoint)) return true\n      // 0.2.0 新增的插件管理器页：普通用户只读（listPlugins/listBundles/registries/inspect）——\n      // 与 0.1.5 的 pluginInventory/list 同理，被拒会让整页显示失败；安装/卸载/启停与\n      // pluginRegistryProbe/* 是部署方能力，仍未登记 → 默认拒绝。\n      if (endpoint.startsWith('pluginManager/')) {\n        return PLUGIN_MANAGER_READ.has(endpoint.slice('pluginManager/'.length))\n      }\n      // 权限预设目录是只读元数据（写入走 settings/mutate，仍限管理员）。\n      if (endpoint === 'permissionPresets/catalog') return true\n      // 交互式提问（作答 / 等待）本质属于某个会话：agentId 或 sessionId 任一属于请求者即放行。\n      if (SESSION_INTERACTIVE.has(endpoint)) {\n        return agent(principal, args) || session(principal, request.sessionId ?? args.sessionId)\n      }\n      // 文档预览（Q8：用户 + 会话 + 工作区三重归属）。宿主以 workspaceFileScope（SessionId）\n      // 解析路径，所以该 scope 必须属于请求者；入参若另给 workspaceId，其归属也必须一致。\n      // 缺少可证明归属的 scope 时拒绝（fail-closed），不做\"仅凭 path 放行\"的推断。\n      if (endpoint.startsWith('officeToPdf/')) {\n        const scope = Array.isArray(raw) ? raw[OFFICE_TO_PDF_SCOPE_INDEX] : args.workspaceFileScopeId\n        if (!session(principal, scope)) return false\n        const workspaceId = Array.isArray(raw) ? undefined : args.workspaceId\n        return workspaceId === undefined || workspace(principal, workspaceId)\n      }\n      // open-in-app 的应用清单按会话归属（等价于按用户）。\n      if (endpoint === 'session/workspacePathApplications') {\n        return session(principal, request.sessionId ?? args.sessionId)\n      }\n      // 账户页（DeepSeek 登录 / 余额 / 充值）读的是**部署者**的账号与钱包，普通用户整体不开放\n      // （Q7）；余额改由本插件的 balanceQuery 按用户自己的配置提供。此处显式拒绝以便审计。\n      if (namespace === 'account') return false\n      // Agent 预设：读清单与\"为本次会话选择预设\"是普通用户的正常能力——设置面板的【Agent 预设】\n      // 页在加载时先调 agentPresets/list（被拒会让整页显示「无法加载 Agent 预设」），新建会话的\n      // 预设选择器同样依赖它。read/select 是 agent 作用域（wire 名 agentId），按会话属主校验。\n      // 只有 copy/deletePreset 会写出新的预设组合（可挂载插件与提示词），仍限管理员。\n      if (endpoint === 'agentPresets/list') return true\n      if (endpoint === 'agentPresets/read' || endpoint === 'agentPresets/select') return agent(principal, args)\n      // 插件清单：普通用户可以查看本部署已安装的插件（只读），但安装/卸载/插件设置仍限管理员。\n      // 白名单按端点登记，因此宿主后续新增的 pluginInventory/* 写操作默认仍是被拒的。\n      if (endpoint === 'pluginInventory/list') return true\n      if (namespace === 'session') {\n        if (SESSION_READ.has(method as string)) return true\n        if (method === 'page' || method === 'follow') return authorizeSession(args, principal)\n        if (method === 'create') {\n          // A deployment-provisioned Workspace owns the location; a client cannot override it with cwd.\n          if (!workspace(principal, request.workspaceId) || request.cwd !== undefined) return false\n          if (request.sessionId === undefined) return true\n          if (!nonempty(request.sessionId)) return false\n          return session(principal, request.sessionId) || !(await owners.sessionExists(request.sessionId))\n        }\n        if (SESSION_BY_ID.has(method as string)) {\n          if (method === 'selectModel') {\n            // R2：切换模型必须落在该用户被授权的 provider/model 之内（未配置授权时维持原行为）。\n            const scope = await entitlementOf(principal)\n            if (scope !== undefined) {\n              const provider = request.provider ?? args.provider\n              const model = request.model ?? args.model\n              if (!allowedProvider(scope, provider) || !allowedModel(scope, provider, model)) return false\n            }\n          }\n          return session(principal, request.sessionId)\n        }\n        return false\n      }\n      if (namespace === 'workspace') {\n        if (method === 'archiveSession') return session(principal, request.sessionId)\n        if (WORKSPACE_BY_ID.has(method as string)) {\n          if (!workspace(principal, request.workspaceId)) return false\n          if (request.beforeWorkspaceId !== undefined && !workspace(principal, request.beforeWorkspaceId)) return false\n          return [request.sessionId, request.beforeSessionId].every(id => id === undefined || session(principal, id))\n        }\n        // Workspace creation stays deployment-owned: a path is a host capability, not a user one.\n        return false\n      }\n      if (namespace === 'workspaceFiles') return session(principal, args.workspaceFileScopeId)\n      if (endpoint === 'skills/list') return session(principal, request.sessionId)\n      if (endpoint === 'fileReferences/list') return agent(principal, args)\n      if (endpoint === 'sessionReferenceResolver/candidates') return agent(principal, args)\n      if (endpoint === 'fileUploads/upload') return agent(principal, args)\n      if (endpoint === 'commands/list') return agent(principal, args)\n      if (namespace === 'goals') return agent(principal, args)\n      if (namespace === 'messageFeedback') return session(principal, request.sessionId)\n      if (endpoint === 'sessionFeedback/record') return session(principal, request.sessionId)\n      // Commands may change permissions, filesystem access or plugins; deployments opt in per command.\n      // Settings/credentials/plugins/presets/directory picking/dynamic Cordis stay administrator-only.\n      return false\n    },\n    async result(principal, endpoint, value) {\n      const record = object(value) ? value : undefined\n      if (record !== undefined && ['session/create', 'session/fork'].includes(endpoint) && nonempty(record.sessionId)) {\n        await owners.claimSession(record.sessionId, principal.username)\n      }\n      if (principal.role === 'admin') return value\n      // R2：按登录用户裁剪模型目录与 provider 列表。\n      // 真实 0.2.0 形状（实测）：`{ default:{provider,model}, routableProviders:[id], groups:[{id,name,models:[{id,…}]}] }`；\n      // 仍兼容早期猜测的 `providers` 字段名。形状不认识时原样返回，绝不误删。\n      const modelScope = await entitlementOf(principal)\n      if (modelScope !== undefined) {\n        if (endpoint === 'session/modelCatalog' && record !== undefined) {\n          const groupKey = Array.isArray(record.groups) ? 'groups' : (Array.isArray(record.providers) ? 'providers' : undefined)\n          if (groupKey !== undefined) {\n            const groups = (record[groupKey] as unknown[]).flatMap(group => {\n              const provider = rowId(group)\n              if (!allowedProvider(modelScope, provider)) return []\n              const models = object(group) && Array.isArray(group.models) ? group.models : undefined\n              if (models === undefined) return [group]\n              const kept = models.filter(model => allowedModel(modelScope, provider, rowModel(model)))\n              return kept.length === 0 ? [] : [{ ...(group as JsonObject), models: kept }]\n            })\n            const routable = Array.isArray(record.routableProviders)\n              ? (record.routableProviders as unknown[]).filter(provider => allowedProvider(modelScope, provider))\n              : undefined\n            const defaultSelection = object(record.default) ? record.default : undefined\n            const keepDefault = defaultSelection !== undefined\n              && allowedProvider(modelScope, rowId(defaultSelection))\n              && allowedModel(modelScope, rowId(defaultSelection), rowModel(defaultSelection))\n            return {\n              ...record,\n              [groupKey]: groups,\n              ...(routable === undefined ? {} : { routableProviders: routable }),\n              // 默认选择若已不在授权内就清空，避免界面把越界模型当作默认值回填。\n              ...(defaultSelection === undefined || keepDefault ? {} : { default: undefined }),\n            }\n          }\n        }\n        if ((endpoint === 'llm/listProviders' || endpoint === 'llm/listConfigurableProviders') && Array.isArray(value)) {\n          return (value as unknown[]).filter(row => allowedProvider(modelScope, rowId(row)))\n        }\n      }\n      if (['session/list', 'session/search'].includes(endpoint)) {\n        const all = arrayOf(record?.items)\n        const items = all.filter(item => session(principal, object(item) ? item.sessionId : undefined))\n        const filtered = items.length < ((record?.items as unknown[] | undefined)?.length ?? 0)\n        return { ...(record ?? {}), items, ...(filtered && record !== undefined && 'hasMore' in record ? { hasMore: false } : {}) }\n      }\n      if (record !== undefined && Array.isArray(record.workspaceIds)) {\n        return { ...record, workspaceIds: record.workspaceIds.filter(id => workspace(principal, id)) }\n      }\n      if (record !== undefined && Array.isArray(record.archivedSessionIds)) {\n        return { ...record, archivedSessionIds: record.archivedSessionIds.filter(id => session(principal, id)) }\n      }\n      if (record !== undefined && record.workspace !== undefined) {\n        return { ...record, workspace: workspaceValue(principal, object(record.workspace) ? record.workspace : {}) }\n      }\n      return value\n    },\n    frame(principal, endpoint, value, correlation) {\n      const frame = object(value) ? value : {}\n      if (endpoint === '$events') {\n        if (frame.type === 'ready') { correlation.clientId = frame.clientId as string; return value }\n        if (frame.type === 'waterfall') {\n          // Only a waterfall whose owning Session belongs to this principal is delivered;\n          // a hidden recipient is released by the gateway with `next` (see modern-gateway).\n          if (!session(principal, frame.agentId)) return null\n          if (correlation.events.size >= 512) throw new Error('Too many pending Remote events')\n          correlation.events.add(frame.eventId as string)\n          return value\n        }\n        if (frame.type === 'cancel') return correlation.events.delete(frame.eventId as string) ? value : null\n        if (frame.type !== 'emit') return null\n        // Global registries (commands/change, credentials/reference-updated, llm/adapters-updated,\n        // settings/document-updated, cordis/*-resolved, cordis/dynamic-*) carry no owner and are\n        // therefore not shown to ordinary users.\n        const args = arrayOf(frame.args) as Array<unknown>\n        // 会话事件的载荷有两种形态：**id 字符串**（如 api-session/removed）与**摘要对象**\n        // （如 api-session/added 用 summaryFor(session)，字段名可能是 sessionId 或 id）。\n        // 只认一种会让**拥有者本人也收不到**自己的实时会话（实测：谁都收不到）。\n        const argSessionId = (arg: unknown): string | undefined => {\n          if (typeof arg === 'string') return arg\n          if (!object(arg)) return undefined\n          const record = arg as JsonObject\n          if (typeof record.sessionId === 'string') return record.sessionId\n          if (typeof record.id === 'string') return record.id\n          return undefined\n        }\n        switch (frame.event) {\n          case 'api-session/added':\n          case 'api-session/activity':\n          case 'api-session/error':\n          case 'api-session/removed':\n          case 'api-session/status': return session(principal, argSessionId(args[0])) ? value : null\n          case 'agent-preset/selected': return session(principal, args[0] as string) ? value : null\n          case 'goal/activation-changed': return session(principal, argSessionId(args[0])) ? value : null\n          case 'cordis/request-run':\n          case 'cordis/inspect-query': {\n            const first = args[0]\n            const agentId = object(first) && typeof (first as JsonObject).agentId === 'string' ? (first as JsonObject).agentId as string : undefined\n            return session(principal, agentId) ? value : null\n          }\n          default: return null\n        }\n      }\n      if (principal.role === 'admin') return value\n      if (endpoint === 'session/control') {\n        if (frame.type === 'baseline') {\n          const baseline = object(frame.value) ? frame.value : {}\n          return { type: 'baseline', value: {\n            queues: ownMap(principal, baseline.queues),\n            jobs: ownMap(principal, baseline.jobs),\n            projections: ownMap(principal, baseline.projections),\n          } }\n        }\n        return session(principal, frame.sessionId) ? value : null\n      }\n      if (endpoint === 'workspace/follow') {\n        if (frame.type === 'baseline') return { type: 'baseline', value: workspaceBaseline(principal, frame.value) }\n        if (frame.type === 'order') return { ...frame, workspaceIds: arrayOf(frame.workspaceIds).filter(id => workspace(principal, id)) }\n        if (frame.type === 'archived') return { ...frame, archivedSessionIds: arrayOf(frame.archivedSessionIds).filter(id => session(principal, id)) }\n        if (frame.type === 'upsert') {\n          const workspaceFrame = object(frame.workspace) ? frame.workspace : undefined\n          return workspace(principal, workspaceFrame?.workspaceId) && workspaceFrame !== undefined\n            ? { ...frame, workspace: workspaceValue(principal, workspaceFrame) }\n            : null\n        }\n        if (frame.type === 'remove') return workspace(principal, frame.workspaceId) ? value : null\n        return null\n      }\n      return value\n    },\n  }\n}\n"
    },
    {
      "path": "src/profile-kek.ts",
      "content": "/**\n * WP4：会话密钥生命周期与私有配置的**信封加密**（见 docs/RBAC-MODEL-PROFILES.md 附录 A.5）。\n *\n * 结构：\n *   userKek = PBKDF2-SHA256(登录口令, 用户级 salt, ≥600k)      ← 只存在于该用户会话内存\n *   dek     = 随机 32 字节                                       ← 每条私有配置一个\n *   记录     = { wrappedDek: seal(userKek, aad, dek), sealed: seal(dek, aad, apiKey) }\n *   aad     = `${uid}/${profileId}`（密文不能在别处重放）\n *\n * 因此：存储里没有明文 Key，也没有能解出它的单一服务端密钥；口令变更只需用旧 KEK 解出 DEK\n * 再用新 KEK 重包裹；会话**不持有口令**，登出即丢弃 userKek。\n */\nimport {\n  DEFAULT_KDF_ITERATIONS, deriveKek, openUnder, profileKey, randomDek, sealUnder,\n  type ProfileSeam, type SealedKey,\n} from './model-profiles.js'\n\nconst keyKdf = (uid: string): string => profileKey(`profile-kdf-${uid}`)\n\ninterface KdfDoc {\n  readonly v: 1\n  readonly salt: string\n  readonly iterations: number\n}\n\nconst toBase64 = (bytes: Uint8Array): string => Buffer.from(bytes).toString('base64')\nconst fromBase64 = (value: string): Uint8Array<ArrayBuffer> => new Uint8Array(Buffer.from(value, 'base64'))\n\nfunction randomSalt(): Uint8Array<ArrayBuffer> {\n  const salt = new Uint8Array(16)\n  const value = (globalThis as { crypto?: Crypto }).crypto\n  if (value?.getRandomValues === undefined) throw new Error('安全随机源不可用')\n  value.getRandomValues(salt)\n  return salt\n}\n\nconst aadOf = (uid: string, profileId: string): string => `${uid}/${profileId}`\n\n/** 读取（必要时创建）用户级 KDF 参数。每人一份，改密时沿用同一 salt 亦可重新生成。 */\nexport async function ensureUserKdf(\n  seam: ProfileSeam, uid: string, iterations = DEFAULT_KDF_ITERATIONS,\n): Promise<{ salt: string; iterations: number }> {\n  const raw = await seam.readRaw(keyKdf(uid))\n  if (raw !== undefined) {\n    const parsed = JSON.parse(raw) as Partial<KdfDoc>\n    if (parsed.v === 1 && typeof parsed.salt === 'string' && typeof parsed.iterations === 'number') {\n      return { salt: parsed.salt, iterations: parsed.iterations }\n    }\n  }\n  const salt = toBase64(randomSalt())\n  await seam.writeRaw(keyKdf(uid), JSON.stringify({ v: 1, salt, iterations } satisfies KdfDoc))\n  return { salt, iterations }\n}\n\n/** 读取用户级 KDF 参数（不存在则 undefined，用于判断该用户是否已启用私有配置）。 */\nexport async function readUserKdf(seam: ProfileSeam, uid: string): Promise<{ salt: string; iterations: number } | undefined> {\n  const raw = await seam.readRaw(keyKdf(uid))\n  if (raw === undefined) return undefined\n  const parsed = JSON.parse(raw) as Partial<KdfDoc>\n  return parsed.v === 1 && typeof parsed.salt === 'string' && typeof parsed.iterations === 'number'\n    ? { salt: parsed.salt, iterations: parsed.iterations }\n    : undefined\n}\n\n/** 写入用户级 KDF 参数（改密时换新 salt）。 */\nexport async function writeUserKdf(\n  seam: ProfileSeam, uid: string, value: { salt: string; iterations: number },\n): Promise<void> {\n  await seam.writeRaw(keyKdf(uid), JSON.stringify({ v: 1, salt: value.salt, iterations: value.iterations } satisfies KdfDoc))\n}\n\n/** 生成一组新的用户级 KDF 参数（不落盘）。 */\nexport function newUserKdf(iterations = DEFAULT_KDF_ITERATIONS): { salt: string; iterations: number } {\n  return { salt: toBase64(randomSalt()), iterations }\n}\n\n/** 口令 + 用户级 salt → userKek（会话内存中持有；不保存口令）。 */\nexport async function deriveUserKek(password: string, saltB64: string, iterations: number): Promise<Uint8Array<ArrayBuffer>> {\n  return await deriveKek(password, fromBase64(saltB64), iterations)\n}\n\n/** 用 userKek 封存一条私有配置：随机 DEK 包进 wrappedDek，API Key 用 DEK 加密。 */\nexport async function sealPrivateWithKek(\n  userKek: Uint8Array<ArrayBuffer>, uid: string, profileId: string, apiKey: string,\n): Promise<{ wrappedDek: SealedKey; sealed: SealedKey }> {\n  const dek = randomDek()\n  const aad = aadOf(uid, profileId)\n  return { wrappedDek: await sealUnder(userKek, aad, Buffer.from(dek).toString('base64')), sealed: await sealUnder(dek, aad, apiKey) }\n}\n\n/** 解开一条私有配置的 API Key；userKek 不对、篡改或 AAD 不匹配都会抛错。 */\nexport async function openPrivateWithKek(\n  userKek: Uint8Array<ArrayBuffer>, uid: string, profileId: string, wrappedDek: SealedKey, sealed: SealedKey,\n): Promise<string> {\n  const aad = aadOf(uid, profileId)\n  const dek = fromBase64(await openUnder(userKek, aad, wrappedDek))\n  return await openUnder(dek, aad, sealed)\n}\n\n/** 口令变更：用旧 KEK 解出 DEK、再用新 KEK 重包裹（改密流程持有明文口令那一刻完成）。 */\nexport async function rewrapWithKek(\n  oldKek: Uint8Array<ArrayBuffer>, newKek: Uint8Array<ArrayBuffer>, uid: string, profileId: string, wrappedDek: SealedKey,\n): Promise<SealedKey> {\n  const aad = aadOf(uid, profileId)\n  const dek = fromBase64(await openUnder(oldKek, aad, wrappedDek))\n  return await sealUnder(newKek, aad, Buffer.from(dek).toString('base64'))\n}\n\n/** 登录会话持有的 userKek（token → uid + KEK）。登出/过期/改密即丢弃。 */\nexport class KekRegistry {\n  private readonly byToken = new Map<string, { uid: string; kek: Uint8Array<ArrayBuffer> }>()\n\n  set(token: string, uid: string, kek: Uint8Array<ArrayBuffer>): void {\n    this.byToken.set(token, { uid, kek })\n  }\n\n  get(token: string): { uid: string; kek: Uint8Array<ArrayBuffer> } | undefined {\n    return this.byToken.get(token)\n  }\n\n  /** 解锁某条配置所需的 KEK（仅当会话 uid 与配置所有者一致）。 */\n  kekFor(token: string, ownerUid: string): Uint8Array<ArrayBuffer> | undefined {\n    const entry = this.byToken.get(token)\n    if (entry === undefined || entry.uid !== ownerUid) return undefined\n    return entry.kek\n  }\n\n  /** 丢弃单个会话（登出、会话失效）。 */\n  drop(token: string): void {\n    this.byToken.delete(token)\n  }\n\n  /** 丢弃某个用户的全部会话（用户被删除、口令被重置、角色变更）。 */\n  dropByUid(uid: string): number {\n    let dropped = 0\n    for (const [token, entry] of [...this.byToken.entries()]) {\n      if (entry.uid !== uid) continue\n      this.byToken.delete(token)\n      dropped += 1\n    }\n    return dropped\n  }\n\n  size(): number {\n    return this.byToken.size\n  }\n}"
    },
    {
      "path": "test/modern-policy.test.mjs",
      "content": "import { test } from 'node:test'\nimport assert from 'node:assert/strict'\nimport { createModernPolicy } from '../lib/modern-policy.js'\n\nconst alice = { username: 'alice', role: 'user' }\nconst owners = { session: id => id === 'a' ? 'alice' : 'bob', workspace: id => id === 'wa' ? 'alice' : 'bob', sessionExists: async id => id !== 'new', claimSession: async () => {} }\nconst policy = createModernPolicy(owners)\nconst request = value => ({ args: { request: value } })\n\ntest('current unary and logical-stream session access uses the nested request', async () => {\n  for (const method of ['prompt', 'attachment', 'cancel', 'fork']) {\n    assert.equal(await policy.authorize(alice, `session/${method}`, request({ sessionId: 'a' })), true)\n    assert.equal(await policy.authorize(alice, `session/${method}`, request({ sessionId: 'b' })), false)\n  }\n  for (const method of ['page', 'follow']) {\n    assert.equal(await policy.authorize(alice, `session/${method}`, request({ address: { kind: 'session', sessionId: 'a' } })), true)\n    assert.equal(await policy.authorize(alice, `session/${method}`, request({ address: { kind: 'session', sessionId: 'b' } })), false)\n    assert.equal(await policy.authorize(alice, `session/${method}`, request({ address: { kind: 'subagent', parentSessionId: 'b', childSessionId: 'a' } })), false)\n  }\n  assert.equal(await policy.authorize(alice, 'session/page', { sessionId: 'a' }), false)\n  // 0.1.5: session/follow is a stream endpoint; the same address check must hold with the stream flag.\n  assert.equal(await policy.authorize(alice, 'session/follow', request({ address: { kind: 'session', sessionId: 'a' } }), true), true)\n  assert.equal(await policy.authorize(alice, 'session/follow', request({ address: { kind: 'session', sessionId: 'b' } }), true), false)\n})\n\ntest('unreviewed endpoints, global settings and arbitrary paths are refused', async () => {\n  for (const method of ['session/futureRead', 'settings/update', 'credentials/set', 'workspace/create', 'commands/execute', 'reports/runs']) {\n    assert.equal(await policy.authorize(alice, method, request({ sessionId: 'a' })), false)\n  }\n  assert.equal(await policy.authorize(alice, 'session/create', request({ workspaceId: 'wa', cwd: '/bob' })), false)\n})\n\ntest('agent presets: the roster is readable, per-session use is owner-scoped, authoring stays admin-only', async () => {\n  // 回归：ordinary 用户的【Agent 预设】设置页在加载时调用 agentPresets/list，\n  // 被 deny-by-default 拒绝会让整页显示「无法加载 Agent 预设」。\n  assert.equal(await policy.authorize(alice, 'agentPresets/list', { args: {} }), true)\n  // read/select 是 agent 作用域：只允许作用在自己拥有的会话上。\n  for (const method of ['agentPresets/read', 'agentPresets/select']) {\n    assert.equal(await policy.authorize(alice, method, { args: { agentId: 'a', agentPreset: 'p' } }), true)\n    assert.equal(await policy.authorize(alice, method, { args: { agentId: 'b', agentPreset: 'p' } }), false)\n    assert.equal(await policy.authorize(alice, method, { args: {} }), false)\n  }\n  // 写出新的预设组合（可挂载插件与提示词）仍限管理员。\n  for (const method of ['agentPresets/copy', 'agentPresets/deletePreset']) {\n    assert.equal(await policy.authorize(alice, method, { args: { from: 'p', id: 'x', name: 'x' } }), false)\n  }\n  assert.equal(await policy.authorize({ username: 'root', role: 'admin' }, 'agentPresets/deletePreset', { args: { id: 'p' } }), true)\n})\n\ntest('plugin inventory: the installed list is readable, mutating plugin endpoints stay closed', async () => {\n  // 回归：普通用户的【插件】设置页只读清单（安装/卸载不是本项目的 RPC 面，白名单按端点登记）。\n  assert.equal(await policy.authorize(alice, 'pluginInventory/list', { args: {} }), true)\n  for (const method of [\n    'pluginInventory/install',\n    'pluginInventory/uninstall',\n    'pluginInventory/enable',\n    'pluginInventory/disable',\n    'pluginInventory/update',\n  ]) {\n    assert.equal(await policy.authorize(alice, method, { args: { name: 'x' } }), false)\n  }\n})\n\ntest('creation requires an owned Workspace and checks cold identity adoption', async () => {\n  assert.equal(await policy.authorize(alice, 'session/create', request({ workspaceId: 'wa', sessionId: 'new' })), true)\n  assert.equal(await policy.authorize(alice, 'session/create', request({ workspaceId: 'wa', sessionId: 'b' })), false)\n  assert.equal(await policy.authorize(alice, 'session/create', request({ workspaceId: 'wb' })), false)\n})\n\ntest('every key in the control baseline is filtered', () => {\n  const data = { a: { text: 'mine' }, b: { text: 'private' } }\n  assert.deepEqual(policy.frame(alice, 'session/control', { type: 'baseline', value: { queues: data, jobs: data, projections: data } }), {\n    type: 'baseline', value: { queues: { a: data.a }, jobs: { a: data.a }, projections: { a: data.a } },\n  })\n  assert.equal(policy.frame(alice, 'session/control', { type: 'jobs', sessionId: 'b', jobs: ['private'] }), null)\n})\n\ntest('Workspace baselines, membership, order and archive frames stay scoped', () => {\n  const frame = policy.frame(alice, 'workspace/follow', { type: 'baseline', value: { items: [\n    { workspaceId: 'wa', sessionIds: ['a', 'b'] }, { workspaceId: 'wb', sessionIds: ['b'] },\n  ], archivedSessionIds: ['a', 'b'] } })\n  assert.deepEqual(frame.value, { items: [{ workspaceId: 'wa', sessionIds: ['a'] }], archivedSessionIds: ['a'] })\n  assert.deepEqual(policy.frame(alice, 'workspace/follow', { type: 'order', workspaceIds: ['wa', 'wb'] }).workspaceIds, ['wa'])\n  assert.equal(policy.frame(alice, 'workspace/follow', { type: 'upsert', workspace: { workspaceId: 'wb' } }), null)\n})\n\ntest('Remote approval delivery retains only owned event correlations', () => {\n  const correlation = { events: new Set() }\n  const other = { type: 'waterfall', agentId: 'b', eventId: 'other' }\n  assert.equal(policy.frame(alice, '$events', other, correlation), null)\n  const own = { type: 'waterfall', agentId: 'a', eventId: 'own' }\n  assert.deepEqual(policy.frame(alice, '$events', own, correlation), own)\n  assert.deepEqual([...correlation.events], ['own'])\n  assert.equal(policy.frame(alice, '$events', { type: 'cancel', eventId: 'other' }, correlation), null)\n  policy.frame(alice, '$events', { type: 'cancel', eventId: 'own' }, correlation)\n  assert.equal(correlation.events.size, 0)\n})\n\ntest('Host events without reviewed scope do not leak plugin or credential activity', () => {\n  assert.equal(policy.frame(alice, '$events', { type: 'emit', event: 'credentials/reference-updated', args: ['private-key'] }, {}), null)\n  assert.equal(policy.frame(alice, '$events', { type: 'emit', event: 'api-session/status', args: ['b', true] }, {}), null)\n  const own = { type: 'emit', event: 'api-session/added', args: [{ sessionId: 'a' }] }\n  assert.deepEqual(policy.frame(alice, '$events', own, {}), own)\n})\n\ntest('creation does not return before ownership persistence', async () => {\n  let finish\n  const pending = new Promise(resolve => { finish = resolve })\n  const guarded = createModernPolicy({ ...owners, claimSession: () => pending })\n  let returned = false\n  const result = guarded.result(alice, 'session/create', { sessionId: 'new' }).then(() => { returned = true })\n  await Promise.resolve()\n  assert.equal(returned, false)\n  finish()\n  await result\n  assert.equal(returned, true)\n})\n\n// ---- 0.1.5 surface additions -------------------------------------------------\n\ntest('workspaceFiles is scoped by the owning Session', async () => {\n  const scope = id => ({ args: { workspaceFileScopeId: id, path: 'a.txt' } })\n  for (const method of ['read', 'readBytes', 'readAll', 'readRelated', 'stat', 'list']) {\n    assert.equal(await policy.authorize(alice, `workspaceFiles/${method}`, scope('a')), true)\n    assert.equal(await policy.authorize(alice, `workspaceFiles/${method}`, scope('b')), false)\n  }\n  assert.equal(await policy.authorize(alice, 'workspaceFiles/changes', scope('a'), true), true)\n  assert.equal(await policy.authorize(alice, 'workspaceFiles/changes', scope('b'), true), false)\n})\n\ntest('agent-scoped verbs follow the owning Session', async () => {\n  const agent = id => ({ args: { agentId: id } })\n  assert.equal(await policy.authorize(alice, 'commands/list', agent('a')), true)\n  assert.equal(await policy.authorize(alice, 'commands/list', agent('b')), false)\n  assert.equal(await policy.authorize(alice, 'goals/get', agent('a')), true)\n  assert.equal(await policy.authorize(alice, 'goals/create', agent('b')), false)\n  assert.equal(await policy.authorize(alice, 'fileUploads/upload', agent('a')), true)\n  assert.equal(await policy.authorize(alice, 'fileReferences/list', agent('a')), true)\n  assert.equal(await policy.authorize(alice, 'sessionReferenceResolver/candidates', agent('a')), true)\n  assert.equal(await policy.authorize(alice, 'skills/list', request({ sessionId: 'a' })), true)\n  assert.equal(await policy.authorize(alice, 'skills/list', request({ sessionId: 'b' })), false)\n})\n\ntest('host-wide administration stays unreachable for ordinary users', async () => {\n  const payload = () => ({ args: {} })\n  for (const endpoint of [\n    'credentials/describe', 'credentials/set', 'credentials/unset',\n    'settings/update', 'settings/replace', 'settings/mutate', 'settings/openSettingsDocument',\n    'directoryPicker/pick', 'directoryPicker/list', 'directoryPicker/createDirectory',\n    'llm/discoverModels', 'agentPresets/read', 'agentPresets/deletePreset',\n    'dynamicCordisRunner/inventory', 'dynamicCordisRunner/invoke', 'dynamicCordisRunner/runHostHalf',\n    'session/openWorkspacePath', 'workspace/create', 'commands/execute', 'subagents/list',\n  ]) {\n    assert.equal(await policy.authorize(alice, endpoint, payload()), false, `${endpoint} must stay closed`)\n  }\n  // Redacted read-only metadata stays available so the UI can render.\n  // （agentPresets/list 与 pluginInventory/list 自 0.6.5 起属于这一档：只读清单可读，写操作仍拒。）\n  assert.equal(await policy.authorize(alice, 'settings/describe', payload()), true)\n  assert.equal(await policy.authorize(alice, 'llm/listProviders', payload()), true)\n  assert.equal(await policy.authorize(alice, 'session/modelCatalog', payload()), true)\n  assert.equal(await policy.authorize(alice, 'agentPresets/list', payload()), true)\n  assert.equal(await policy.authorize(alice, 'pluginInventory/list', payload()), true)\n})\n\ntest('session/list reads the flat _request wire name and is owner-filtered', async () => {\n  assert.equal(await policy.authorize(alice, 'session/list', { args: { _request: {} } }), true)\n  const value = await policy.result(alice, 'session/list', { items: [{ sessionId: 'a' }, { sessionId: 'b' }] })\n  assert.deepEqual(value.items, [{ sessionId: 'a' }])\n})\n\ntest('unattributable forwarded events are not delivered to ordinary users', () => {\n  for (const event of [\n    'commands/change', 'credentials/reference-updated', 'llm/adapters-updated',\n    'settings/document-updated', 'cordis/dynamic-package', 'cordis/dynamic-retract',\n    'cordis/request-run-resolved', 'cordis/inspect-query-resolved',\n  ]) {\n    assert.equal(policy.frame(alice, '$events', { type: 'emit', event, args: [] }, {}), null, `${event} must not leak`)\n  }\n  const ready = { type: 'ready', clientId: 'c1' }\n  const correlation = {}\n  assert.deepEqual(policy.frame(alice, '$events', ready, correlation), ready)\n  assert.equal(correlation.clientId, 'c1')\n})\n\n// ---- v0.7.0 / DSH 0.2.0 新增面（WP2）----\n\ntest('0.2.0 plugin manager: the page reads are open, every write verb stays admin-only', async () => {\n  // 插件管理器页在加载时调 listPlugins/listBundles/registries/inspect；被拒会让整页失败。\n  for (const method of ['listPlugins', 'listBundles', 'registries', 'inspect']) {\n    assert.equal(await policy.authorize(alice, `pluginManager/${method}`, { args: {} }), true)\n    assert.equal(await policy.authorize(alice, `pluginManager/${method}`, { args: {} }, false), true)\n  }\n  // 安装/卸载/启停是部署方能力；凭据探测走网络，同样不开放。\n  for (const method of ['installBundle', 'removeBundle', 'setPluginEnabled', 'setBundleEnabled', 'cancelInstall', 'waitForInstall']) {\n    assert.equal(await policy.authorize(alice, `pluginManager/${method}`, { args: {} }), false)\n  }\n  assert.equal(await policy.authorize(alice, 'pluginRegistryProbe/fastest', { args: {} }), false)\n  assert.equal(await policy.authorize(alice, 'pluginManager/futureWrite', { args: {} }), false)\n  assert.equal(await policy.authorize(alice, 'permissionPresets/catalog', { args: {} }), true)\n  assert.equal(await policy.authorize(alice, 'permissionPresets/set', { args: {} }), false)\n})\n\ntest('question answering is ownership-scoped; the deployment account page stays closed', async () => {\n  for (const method of ['userQuestions/answer', 'userQuestions/attachWait']) {\n    assert.equal(await policy.authorize(alice, method, { args: { agentId: 'a' } }), true)\n    assert.equal(await policy.authorize(alice, method, { args: { agentId: 'b' } }), false)\n    assert.equal(await policy.authorize(alice, method, { args: { sessionId: 'a' } }), true)\n    assert.equal(await policy.authorize(alice, method, { args: { sessionId: 'b' } }), false)\n    assert.equal(await policy.authorize(alice, method, { args: {} }), false)\n  }\n  // Q7：原生账户页读写的是部署者的 DeepSeek 账号与钱包，普通用户一律拒绝（余额走 balanceQuery）。\n  for (const method of ['account/getProfile', 'account/getBalance', 'account/watch', 'account/signOut', 'account/startSignIn', 'account/ackBonusNotified']) {\n    assert.equal(await policy.authorize(alice, method, { args: {} }), false)\n  }\n  // open-in-app 的应用清单按会话归属；账户页的模型初始化不属于用户能力。\n  assert.equal(await policy.authorize(alice, 'session/workspacePathApplications', { args: { sessionId: 'a' } }), true)\n  assert.equal(await policy.authorize(alice, 'session/workspacePathApplications', { args: { sessionId: 'b' } }), false)\n  assert.equal(await policy.authorize(alice, 'session/initializeDefaultModel', { args: { sessionId: 'a' } }), false)\n})\n\ntest('officeToPdf requires a provable scope (Q8: user + session + workspace)', async () => {\n  // 位置参数形态：(workspaceFileScopeId, path, priority)\n  assert.equal(await policy.authorize(alice, 'officeToPdf/render', { args: ['a', 'doc.docx', 'normal'] }), true)\n  assert.equal(await policy.authorize(alice, 'officeToPdf/render', { args: ['b', 'doc.docx', 'normal'] }), false)\n  assert.equal(await policy.authorize(alice, 'officeToPdf/render', { args: ['doc.docx'] }), false) // scope 缺失 → 拒绝\n  assert.equal(await policy.authorize(alice, 'officeToPdf/generation', { args: {} }), false)\n  assert.equal(await policy.authorize(alice, 'officeToPdf/generation', { args: [] }), false)\n  // 命名参数形态：另给 workspaceId 时必须同属请求者，否则拒绝。\n  assert.equal(await policy.authorize(alice, 'officeToPdf/generation', { args: { workspaceFileScopeId: 'a', workspaceId: 'wa' } }), true)\n  assert.equal(await policy.authorize(alice, 'officeToPdf/generation', { args: { workspaceFileScopeId: 'a', workspaceId: 'wb' } }), false)\n  assert.equal(await policy.authorize(alice, 'officeToPdf/render', { args: { workspaceFileScopeId: 'a' } }), true)\n})\n\ntest('R2: a per-user entitlement trims the catalog and gates model selection', async () => {\n  const aliceScope = { providers: ['deepseek'], models: [{ provider: 'deepseek', model: 'deepseek-chat' }] }\n  const restricted = createModernPolicy(owners, { entitlement: principal => principal.username === 'alice' ? aliceScope : undefined })\n\n  // 模型目录：丢掉未授权 provider 分组与未授权模型；未知形状原样返回\n  const catalog = {\n    // 真实 0.2.0 形状（实测）：default + routableProviders + groups\n    default: { provider: 'deepseek', model: 'deepseek-chat' },\n    routableProviders: ['deepseek', 'openai'],\n    groups: [\n      { id: 'deepseek', name: 'DeepSeek', models: [{ id: 'deepseek-chat' }, { id: 'deepseek-reasoner' }] },\n      { id: 'openai', name: 'OpenAI', models: [{ id: 'gpt-4o' }] },\n    ],\n  }\n  const trimmed = await restricted.result(alice, 'session/modelCatalog', catalog)\n  assert.deepEqual(trimmed.groups.map(group => group.id), ['deepseek'])\n  assert.deepEqual(trimmed.groups[0].models.map(model => model.id), ['deepseek-chat'])\n  assert.deepEqual(trimmed.default, catalog.default, '授权内的默认值保留')\n  assert.deepEqual(trimmed.routableProviders, ['deepseek'], 'routableProviders 同步裁剪')\n\n  // provider 列表裁剪\n  const providers = [{ id: 'deepseek' }, { id: 'openai' }]\n  assert.deepEqual(await restricted.result(alice, 'llm/listProviders', providers), [{ id: 'deepseek' }])\n  assert.deepEqual(await restricted.result(alice, 'llm/listConfigurableProviders', providers), [{ id: 'deepseek' }])\n\n  // 切换模型：授权范围内放行，越界或非本会话拒绝\n  assert.equal(await restricted.authorize(alice, 'session/selectModel', { args: { sessionId: 'a', provider: 'deepseek', model: 'deepseek-chat' } }), true)\n  assert.equal(await restricted.authorize(alice, 'session/selectModel', { args: { sessionId: 'a', provider: 'deepseek', model: 'deepseek-reasoner' } }), false)\n  assert.equal(await restricted.authorize(alice, 'session/selectModel', { args: { sessionId: 'a', provider: 'openai', model: 'gpt-4o' } }), false)\n  assert.equal(await restricted.authorize(alice, 'session/selectModel', { args: { sessionId: 'b', provider: 'deepseek', model: 'deepseek-chat' } }), false)\n\n  // 管理员不受裁剪；未提供 entitlement 时行为与以前一致\n  const admin = { username: 'root', role: 'admin' }\n  assert.deepEqual((await restricted.result(admin, 'session/modelCatalog', catalog)), catalog)\n  assert.deepEqual(await restricted.result(alice, 'session/modelCatalog', { groups: 'unknown-shape' }), { groups: 'unknown-shape' })\n  assert.deepEqual(await policy.result(alice, 'session/modelCatalog', catalog), catalog, '未配置授权时不裁剪')\n})\n\n// Issue #3（@HeathZero 报告，PR #5）：自带 HTTP 载体的第三方插件（如 @xmanrui/dsh-im）用\n// `{method, payload}` 而不是标准 `{args}` 信封。此前形状检查在 **admin 放行之前** 执行，\n// 因此连管理员也被判为「畸形」而拒绝（IM 设置页 management-unreachable）。\n// 现在的规则：形状完备的非标信封按**管理员**放行，普通用户维持默认拒绝，且不限于某个命名空间。\ntest('non-standard management envelopes are admin-only, and malformed ones stay denied (issue #3)', async () => {\n  const root = { username: 'root', role: 'admin' }\n  const envelope = { method: 'connection.status', payload: {} }\n\n  // 管理员：HTTP 线（unary）与 mux stream 线共用同一入口，两条都必须放行\n  assert.equal(await policy.authorize(root, 'dsh-im/feishu', envelope), true, 'HTTP 线放行')\n  assert.equal(await policy.authorize(root, 'dsh-im/feishu', envelope, true), true, 'stream 线放行')\n\n  // 普通用户：默认拒绝不变（IM 机器人管理是部署者能力）\n  assert.equal(await policy.authorize(alice, 'dsh-im/feishu', envelope), false)\n  assert.equal(await policy.authorize(alice, 'dsh-im/feishu', envelope, true), false)\n\n  // 形状不完备 = 畸形：管理员也拒绝（fail-closed 不能被\"非标\"绕过）\n  assert.equal(await policy.authorize(root, 'dsh-im/feishu', { method: 'connection.status' }), false, '缺 payload 对象')\n  assert.equal(await policy.authorize(root, 'dsh-im/feishu', { payload: {} }), false, '缺 method')\n  assert.equal(await policy.authorize(root, 'dsh-im/feishu', { method: 1, payload: {} }), false, 'method 非字符串')\n\n  // 泛化：不硬编码 dsh-im 命名空间，其他插件的非标管理端点同样适用\n  assert.equal(await policy.authorize(root, 'other-plugin/manage', envelope), true)\n  assert.equal(await policy.authorize(alice, 'other-plugin/manage', envelope), false)\n\n  // 既有行为不回归：标准信封仍按原规则（读端点放行、未登记端点拒绝）\n  assert.equal(await policy.authorize(root, 'session/list', { args: {} }), true)\n  assert.equal(await policy.authorize(alice, 'session/list', { args: {} }), true)\n  assert.equal(await policy.authorize(alice, 'unreviewed/endpoint', { args: {} }), false)\n})\n"
